def search(a, target, verbose=True):
    left, right = 0, len(a) - 1
    while left <= right:
        mid = left + (right - left) // 2
        if verbose:
            print(f"  range [{left}, {right}] mid={mid} a[mid]={a[mid]}")
        if a[mid] == target:
            return mid
        if a[mid] < target:
            left = mid + 1   # target can only be to the right
        else:
            right = mid - 1  # target can only be to the left
    return -1


def lower_bound(a, target):
    """First index with a[i] >= target (half-open range [left, right))."""
    left, right = 0, len(a)
    while left < right:
        mid = left + (right - left) // 2
        if a[mid] < target:
            left = mid + 1
        else:
            right = mid
    return left


def upper_bound(a, target):
    """First index with a[i] > target."""
    left, right = 0, len(a)
    while left < right:
        mid = left + (right - left) // 2
        if a[mid] <= target:
            left = mid + 1
        else:
            right = mid
    return left


