        self.value = value
        self.next = next


class SinglyLinkedList:
    def __init__(self):
        self.head = None

    def add_first(self, value):
        self.head = Node(value, self.head)

    def add_last(self, value):
        fresh = Node(value)
        if self.head is None:
            self.head = fresh
            return
        n = self.head
        while n.next:  # walk to the last node: O(n)
            n = n.next
        n.next = fresh

    def insert_after(self, node, value):
        node.next = Node(value, node.next)  # the new node points at the rest first

    def remove(self, value):
        if self.head is None:
            return False
        if self.head.value == value:  # deleting the head
            self.head = self.head.next
            return True
        prev = self.head
        while prev.next and prev.next.value != value:
            prev = prev.next
        if prev.next is None:
            return False  # not found
        prev.next = prev.next.next  # skip over the node
        return True

    def find(self, value):
        n = self.head
        while n and n.value != value:
            n = n.next
        return n

    def __str__(self):
        parts, n = [], self.head
        while n:
            parts.append(f"{n.value} -> ")
            n = n.next
        return "".join(parts) + "null"


