        while n is not self.tail:
            out.append(n.value)
            n = n.next
        return " <-> ".join(out)

    def backward(self):
        out, n = [], self.tail.prev
        while n is not self.head:
            out.append(n.value)
            n = n.prev
        return " <-> ".join(out)


