class BinarySearchTree:
    def __init__(self):
        self.root = None

    def insert(self, key):
        self.root = self._insert(self.root, key)

    def _insert(self, n, key):
        if n is None:
            return Node(key)
        if key < n.key:
            n.left = self._insert(n.left, key)
        elif key > n.key:
            n.right = self._insert(n.right, key)
        return n

    def search(self, key):
        path, n = [], self.root
        while n:
            path.append(str(n.key))
            if key == n.key:
                break
            n = n.left if key < n.key else n.right  # discard the other subtree
        print(f"search {key}: path {' '.join(path)} -> {'found' if n else 'absent'}")
        return n is not None

    def delete(self, key):
        self.root = self._delete(self.root, key)

    def _delete(self, n, key):
        if n is None:
            return None
        if key < n.key:
            n.left = self._delete(n.left, key)
        elif key > n.key:
            n.right = self._delete(n.right, key)
        else:
            if n.left is None:
                return n.right  # leaf or only a right child
            if n.right is None:
                return n.left   # only a left child
            successor = n.right  # two children: smallest key on the right
            while successor.left:
                successor = successor.left
            n.key = successor.key
            n.right = self._delete(n.right, successor.key)  # remove the successor itself
        return n

    def inorder(self):
        out = []

        def walk(n):
            if n:
                walk(n.left)
                out.append(n.key)
                walk(n.right)
        walk(self.root)
        return out


