        self.pass_count = 0  # words whose path goes through this node
        self.is_word = False


root = Node()


def insert(word):
    n = root
    for c in word:
        n = n.children.setdefault(c, Node())
        n.pass_count += 1
    n.is_word = True


def walk(prefix):
    n = root
    for c in prefix:
        n = n.children.get(c)
        if n is None:
            return None
    return n


def starts_with(prefix):
    return walk(prefix) is not None


def count_with_prefix(prefix):
    n = walk(prefix)
    return 0 if n is None else n.pass_count


def longest_common_prefix():
    out, n = [], root
    while len(n.children) == 1 and not n.is_word:  # a single path and no word ends here
        (c, child), = n.children.items()
        out.append(c)
        n = child
    return "".join(out)


for w in ["interview", "internet", "interval", "internal"]:
    insert(w)
print("longest common prefix:", longest_common_prefix())
for w in ["inter", "intern", "interv", "intra"]:
    print(f"startsWith({w}) = {str(starts_with(w)).lower()}, words with this prefix: {count_with_prefix(w)}")
insert("in")
print('after inserting "in": longest common prefix =', longest_common_prefix())

