class Trie:
    def __init__(self):
        self.root = Node()

    def insert(self, word):
        node = self.root
        for c in word:
            node = node.children.setdefault(c, Node())
        node.is_word = True

    def complete(self, prefix):
        node = self.root
        for c in prefix:
            if c not in node.children:
                return []
            node = node.children[c]
        words = []

        def dfs(n, path):
            if n.is_word:
                words.append(path)
            for c in sorted(n.children):
                dfs(n.children[c], path + c)

        dfs(node, prefix)
        return words


def build(words):
    trie = Trie()
    for w in words:
        trie.insert(w)
    return trie

