from collections import deque


class Node:
    def __init__(self, key):
        self.key, self.height = key, 0
        self.left = self.right = None


def h(n):
    return -1 if n is None else n.height


def balance(n):
    return h(n.left) - h(n.right)


def fix(n):
    n.height = 1 + max(h(n.left), h(n.right))


def rotate_right(y):
    x = y.left
    y.left, x.right = x.right, y
    fix(y)
    fix(x)
    return x


def rotate_left(x):
    y = x.right
    x.right, y.left = y.left, x
    fix(x)
    fix(y)
    return y


def report(kind, n):
    print(f"  node {n.key} has balance {balance(n)}: case {kind}")


def insert(n, key):
    if n is None:
        return Node(key)
    if key < n.key:
        n.left = insert(n.left, key)
    else:
        n.right = insert(n.right, key)
    fix(n)
    b = balance(n)
    if b > 1 and key < n.left.key:
        report("LL", n)
        return rotate_right(n)
    if b < -1 and key > n.right.key:
        report("RR", n)
        return rotate_left(n)
    if b > 1:
        report("LR", n)
        n.left = rotate_left(n.left)
        return rotate_right(n)
    if b < -1:
        report("RL", n)
        n.right = rotate_right(n.right)
        return rotate_left(n)
    return n


def levels(root):
    rows, q = [], deque([root])
    while q:
        row = []
        for _ in range(len(q)):
            n = q.popleft()
            row.append(f"{n.key}({balance(n)})")
            if n.left:
                q.append(n.left)
            if n.right:
                q.append(n.right)
        rows.append(" ".join(row))
    return " | ".join(rows)


