    power = [1] * (len(s) + 1)
    for i, ch in enumerate(s):
        prefix[i + 1] = (prefix[i] * B + ord(ch)) % M
        power[i + 1] = power[i] * B % M


def hash_of(l, r):
    """Hash of s[l:r] in O(1); Python's % is already non-negative."""
    return (prefix[r] - prefix[l] * power[r - l]) % M


def same(a, b, length):
    return hash_of(a, a + length) == hash_of(b, b + length)


def repeated_start(length):
    """Start of a repeated substring of this length, or -1."""
    seen = set()
    for i in range(len(s) - length + 1):
        h = hash_of(i, i + length)
        if h in seen:
            return i
        seen.add(h)
    return -1


